#!/bin/sh
# Installs the material generated by `sensor-pipeline provision-broker` (mounted read-only
# on /broker) where Mosquitto can read it after dropping root, hashes the passwords, then
# starts the broker.
set -eu

secure=/mosquitto/secure
mkdir -p "$secure"
cp /broker/ca.crt /broker/server.crt /broker/server.key /broker/acl "$secure/"
cp /broker/passwords "$secure/passwd"
# Plain "user:password" lines become salted PBKDF2-SHA512 hashes, in place.
mosquitto_passwd -U "$secure/passwd"
chown -R mosquitto:mosquitto "$secure"
chmod 600 "$secure"/*

exec mosquitto -c /mosquitto/config/mosquitto.conf
